begin;
do $$ begin create type public.supplier_request_type as enum ('quotation','moq','pricing_revision','sample','certificate','specification','packaging','photos','video','production_capacity','lead_time','payment_terms','shipping_terms','other'); exception when duplicate_object then null; end $$;
do $$ begin create type public.supplier_request_status as enum ('draft','sent','waiting_response','partially_received','completed','cancelled','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type public.supplier_response_type as enum ('message','quotation','document','certificate','image','video','sample_update','clarification','rejection','other'); exception when duplicate_object then null; end $$;
create table public.supplier_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),supplier_candidate_id uuid not null,request_type public.supplier_request_type not null,subject text not null check(char_length(trim(subject)) between 1 and 240),message text check(message is null or char_length(message)<=8000),status public.supplier_request_status not null default 'draft',assigned_to_profile_id uuid references public.profiles(id) on delete set null,requested_by_profile_id uuid references public.profiles(id) on delete set null,sent_at timestamptz,due_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,internal_notes text check(internal_notes is null or char_length(internal_notes)<=4000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,foreign key(supplier_candidate_id,organization_id) references public.supplier_candidates(id,organization_id),check((status='completed')=(completed_at is not null)),check((status='cancelled')=(cancelled_at is not null)),check((status='archived')=(archived_at is not null)),check(due_at is null or sent_at is null or due_at>=sent_at));
create table public.supplier_responses(id uuid primary key default gen_random_uuid(),organization_id uuid not null,supplier_request_id uuid not null,response_type public.supplier_response_type not null,message text check(message is null or char_length(message)<=8000),received_at timestamptz not null default now(),received_by_profile_id uuid references public.profiles(id) on delete set null,supplier_contact_id uuid references public.supplier_contacts(id) on delete set null,is_complete_response boolean not null default false,internal_notes text check(internal_notes is null or char_length(internal_notes)<=4000),created_at timestamptz not null default now(),archived_at timestamptz,foreign key(supplier_request_id,organization_id) references public.supplier_requests(id,organization_id));
alter table public.supplier_requests add unique(id,organization_id); create index supplier_requests_candidate_idx on public.supplier_requests(supplier_candidate_id) where archived_at is null; create index supplier_responses_request_idx on public.supplier_responses(supplier_request_id) where archived_at is null;
create trigger supplier_requests_updated before update on public.supplier_requests for each row execute procedure public.set_updated_at();
create or replace function public.assert_rfq_attachment_owner() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.owner_type='rfq' and not exists(select 1 from public.rfqs where id=new.owner_id and organization_id=new.organization_id) then raise exception 'Attachment RFQ owner is not in organization'; end if; if new.owner_type='rfq_item' and not exists(select 1 from public.rfq_items where id=new.owner_id and organization_id=new.organization_id) then raise exception 'Attachment item owner is not in organization'; end if; if new.owner_type='supplier_response' and not exists(select 1 from public.supplier_responses where id=new.owner_id and organization_id=new.organization_id) then raise exception 'Attachment response owner is not in organization'; end if; return new; end; $$;
create or replace function public.is_supplier_request_manager(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','operations','purchasing']::public.app_role[])$$; create or replace function public.is_supplier_request_reader(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','operations','purchasing','inspection','finance']::public.app_role[])$$;
create or replace function public.append_supplier_request_activity() returns trigger language plpgsql security definer set search_path=public as $$ declare target_item uuid; target_rfq uuid; target_event public.rfq_activity_event_type; target_title text; begin
  if tg_op = 'INSERT' then target_event := 'supplier_request_created'; target_title := 'Supplier request created';
  elsif new.status = 'sent' and old.status is distinct from 'sent' then target_event := 'supplier_request_sent'; target_title := 'Supplier request sent';
  elsif new.status = 'cancelled' and old.status is distinct from 'cancelled' then target_event := 'supplier_request_cancelled'; target_title := 'Supplier request cancelled';
  else return new; end if;
  select sc.rfq_item_id into target_item from public.supplier_candidates sc where sc.id = new.supplier_candidate_id and sc.organization_id = new.organization_id;
  select ri.rfq_id into target_rfq from public.rfq_items ri where ri.id = target_item and ri.organization_id = new.organization_id;
  if target_rfq is null then raise exception 'Supplier request candidate is not linked to an RFQ item'; end if;
  insert into public.rfq_activity_events(organization_id,rfq_id,rfq_item_id,event_type,title,visibility,actor_user_id) values(new.organization_id,target_rfq,target_item,target_event,target_title,'internal',coalesce(auth.uid(),new.requested_by_profile_id));
  return new;
end; $$;
create trigger supplier_request_activity_after_insert after insert on public.supplier_requests for each row execute procedure public.append_supplier_request_activity();
create trigger supplier_request_activity_after_status_update after update of status on public.supplier_requests for each row execute procedure public.append_supplier_request_activity();
create or replace function public.append_supplier_response_activity() returns trigger language plpgsql security definer set search_path=public as $$ declare target_candidate uuid; target_item uuid; target_rfq uuid; begin
  select sr.supplier_candidate_id into target_candidate from public.supplier_requests sr where sr.id = new.supplier_request_id and sr.organization_id = new.organization_id;
  select sc.rfq_item_id into target_item from public.supplier_candidates sc where sc.id = target_candidate and sc.organization_id = new.organization_id;
  select ri.rfq_id into target_rfq from public.rfq_items ri where ri.id = target_item and ri.organization_id = new.organization_id;
  if target_rfq is null then raise exception 'Supplier response request is not linked to an RFQ item'; end if;
  insert into public.rfq_activity_events(organization_id,rfq_id,rfq_item_id,event_type,title,visibility,actor_user_id) values(new.organization_id,target_rfq,target_item,'supplier_response_received','Supplier response received','internal',coalesce(auth.uid(),new.received_by_profile_id));
  return new;
end; $$;
create trigger supplier_response_activity_after_insert after insert on public.supplier_responses for each row execute procedure public.append_supplier_response_activity();
alter table public.supplier_requests enable row level security; alter table public.supplier_responses enable row level security; revoke all on public.supplier_requests,public.supplier_responses from anon,authenticated; grant select,insert,update on public.supplier_requests,supplier_responses to authenticated;
create policy "request read" on public.supplier_requests for select to authenticated using(public.is_supplier_request_reader(organization_id));create policy "request insert" on public.supplier_requests for insert to authenticated with check(public.is_supplier_request_manager(organization_id));create policy "request update" on public.supplier_requests for update to authenticated using(public.is_supplier_request_manager(organization_id)) with check(public.is_supplier_request_manager(organization_id));create policy "response read" on public.supplier_responses for select to authenticated using(public.is_supplier_request_reader(organization_id));create policy "response insert" on public.supplier_responses for insert to authenticated with check(public.is_supplier_request_manager(organization_id));create policy "response update" on public.supplier_responses for update to authenticated using(public.is_supplier_request_manager(organization_id)) with check(public.is_supplier_request_manager(organization_id));
commit;
